import React from 'react';
import ProjectCard from './ProjectCard';
import './Projects.css';

const projects = [
  {
    title: 'Meticulous Cleaning Services',
    description: 'A business website for a cleaning company with service selection, quoting and booking.',
    tech: 'React, Firebase, EmailJS',
    image: '/assets/cleaning.jpg',
    liveLink: 'https://meticulous-cleaning.vercel.app',
  },
  {
    title: 'Invoisseur',
    description: 'A free online invoice maker for freelancers and businesses.',
    tech: 'React, JS, CSS',
    image: '/assets/invoisseur.jpg',
    liveLink: 'https://invoisseur.netlify.app',
  },
  {
    title: 'EzyInvoice',
    description: 'Modern invoicing solution with GitHub integration.',
    tech: 'React, Node.js',
    image: '/assets/ezyinvoice.jpg',
    liveLink: 'https://ezyinvoice.netlify.app',
    githubLink: 'https://github.com/Monwabisindlovu/ezyinvoice'
  },
  {
    title: 'JournalHub',
    description: 'A personal journaling web app.',
    tech: 'Node.js, Express, React',
    image: '/assets/journalhub.jpg',
    githubLink: 'https://github.com/Monwabisindlovu/journalhub'
  },
];

const Projects = () => {
  return (
    <section id="projects" className="projects-section">
      <h2 className="projects-title">Projects</h2>
      <div className="projects-grid">
        {projects.map((project, index) => (
          <ProjectCard key={index} {...project} />
        ))}
      </div>
    </section>
  );
};

export default Projects;
